const listProjectActivity = `-- name: ListProjectActivity :many
SELECT a.id, a.action, a.entity_type, a.entity_id, a.user_id, u.username, a.details, a.created_at
FROM audit_logs a LEFT JOIN users u ON u.id = a.user_id
WHERE a.entity_type IS NOT NULL
  AND (
    (a.entity_type = 'project' AND a.entity_id = $1)
    OR (a.entity_type = 'vulnerability' AND a.entity_id IN (SELECT id FROM vulnerabilities WHERE project_id = $1))
    OR (a.entity_type = 'host' AND a.entity_id IN (SELECT id FROM hosts WHERE project_id = $1))
    OR (a.entity_type = 'port' AND a.entity_id IN (SELECT id FROM ports WHERE host_id IN (SELECT id FROM hosts WHERE project_id = $1)))
    OR (a.entity_type = 'service' AND a.entity_id IN (SELECT id FROM services WHERE port_id IN (SELECT id FROM ports WHERE host_id IN (SELECT id FROM hosts WHERE project_id = $1))))
    OR (a.entity_type = 'endpoint' AND a.entity_id IN (SELECT id FROM endpoints WHERE host_id IN (SELECT id FROM hosts WHERE project_id = $1)))
    OR (a.entity_type = 'project_note' AND a.entity_id IN (SELECT id FROM project_notes WHERE project_id = $1))
    OR (a.entity_type = 'project_member' AND a.entity_id IN (SELECT id FROM project_members WHERE project_id = $1))
    OR (a.details->>'project_id' = $1::text)
  )
ORDER BY a.created_at DESC LIMIT $2
`

