const projectStatsAdmin = `-- name: ProjectStatsAdmin :many
SELECT p.id AS project_id, p.status,
       COALESCE(h.cnt, 0)::bigint AS hosts_count,
       COALESCE(v.total, 0)::bigint AS total_findings,
       COALESCE(v.open, 0)::bigint AS open_findings
FROM projects p
LEFT JOIN (SELECT project_id, count(*) AS cnt FROM hosts GROUP BY project_id) h ON h.project_id = p.id
LEFT JOIN (SELECT project_id, count(*) AS total,
                  count(*) FILTER (WHERE status IN ('OPEN','IN_PROGRESS')) AS open
           FROM vulnerabilities GROUP BY project_id) v ON v.project_id = p.id
ORDER BY p.created_at DESC
`

type ProjectStatsAdminRow struct {
	ProjectID     int32         `json:"project_id"`
	Status        ProjectStatus `json:"status"`
	HostsCount    int64         `json:"hosts_count"`
	TotalFindings int64         `json:"total_findings"`
	OpenFindings  int64         `json:"open_findings"`
}

// ─────────── project stats ───────────
func (q *Queries) ProjectStatsAdmin(ctx context.Context) ([]ProjectStatsAdminRow, error) {
	rows, err := q.db.Query(ctx, projectStatsAdmin)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProjectStatsAdminRow{}
	for rows.Next() {
		var i ProjectStatsAdminRow
		if err := rows.Scan(
			&i.ProjectID,
			&i.Status,
			&i.HostsCount,
			&i.TotalFindings,
			&i.OpenFindings,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

