const updateProject = `-- name: UpdateProject :one
UPDATE projects
SET name = $2, folder = $3, description = $4, start_date = $5, end_date = $6,
    status = $7, timeline_frozen_at = $8, updated_at = now()
WHERE id = $1 RETURNING id, name, folder, description, start_date, end_date, timeline_frozen_at, status, created_by, created_at, updated_at
`

type UpdateProjectParams struct {
	ID               int32              `json:"id"`
	Name             string             `json:"name"`
	Folder           string             `json:"folder"`
	Description      pgtype.Text        `json:"description"`
	StartDate        pgtype.Date        `json:"start_date"`
	EndDate          pgtype.Date        `json:"end_date"`
	Status           ProjectStatus      `json:"status"`
	TimelineFrozenAt pgtype.Timestamptz `json:"timeline_frozen_at"`
}

func (q *Queries) UpdateProject(ctx context.Context, arg UpdateProjectParams) (Project, error) {
	row := q.db.QueryRow(ctx, updateProject,
		arg.ID,
		arg.Name,
		arg.Folder,
		arg.Description,
		arg.StartDate,
		arg.EndDate,
		arg.Status,
		arg.TimelineFrozenAt,
	)
	var i Project
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Folder,
		&i.Description,
		&i.StartDate,
		&i.EndDate,
		&i.TimelineFrozenAt,
		&i.Status,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

